def merge_intervals(intervals):
    """Merge closed integer intervals; return a new sorted list of disjoint [start, end] pairs.

    The input list and its pairs are not modified.
    """
    merged = []
    for start, end in sorted(intervals, key=lambda p: (p[0], p[1])):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged
