def merge_intervals(intervals):
    """Merge closed integer intervals.

    Returns a new sorted list of non-overlapping [start, end] pairs.
    Intervals that touch (e.g. [1, 3] and [3, 5]) are merged; the input
    list and its pairs are not modified.

    Time: O(n log n) for sorting; Space: O(n) for the output.
    """
    merged = []
    for start, end in sorted(intervals, key=lambda p: p[0]):
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
