const test = require('node:test');
const assert = require('node:assert/strict');
const { mapLimit } = require('../src/solution.cjs');

// Each call to fn creates a deferred the test resolves manually.
function controlled() {
  const calls = [];
  const fn = (item) =>
    new Promise((resolve, reject) => calls.push({ item, resolve, reject }));
  return { calls, fn };
}
const tick = () => new Promise((r) => setImmediate(r));

test('rejects invalid limits with RangeError', async () => {
  for (const bad of [0, -1, 1.5, NaN, Infinity, '2', undefined]) {
    await assert.rejects(mapLimit([1], bad, async (x) => x), RangeError);
  }
});

test('empty input returns []', async () => {
  assert.deepEqual(await mapLimit([], 3, async (x) => x), []);
});

test('never exceeds limit and starts next as slots free', async () => {
  const { calls, fn } = controlled();
  const p = mapLimit([0, 1, 2, 3, 4], 2, fn);
  await tick();
  assert.equal(calls.length, 2);
  calls[1].resolve('b');
  await tick();
  assert.equal(calls.length, 3);
  calls[0].resolve('a');
  await tick();
  assert.equal(calls.length, 4);
  calls[2].resolve('c');
  calls[3].resolve('d');
  await tick();
  assert.equal(calls.length, 5);
  calls[4].resolve('e');
  assert.deepEqual(await p, ['b', 'a', 'c', 'd', 'e'].map((_, i) => ['a', 'b', 'c', 'd', 'e'][
    // results by input index: item1->'b' is index 1
    i
  ]).map((_, i) => [ 'a', 'b', 'c', 'd', 'e'][i]) && ['b', 'a', 'c', 'd', 'e']);
});

test('results keep input order when calls finish out of order', async () => {
  const { calls, fn } = controlled();
  const p = mapLimit(['x', 'y', 'z'], 3, fn);
  await tick();
  calls[2].resolve('Z');
  calls[0].resolve('X');
  calls[1].resolve('Y');
  assert.deepEqual(await p, ['X', 'Y', 'Z']);
});

test('limit larger than items launches all', async () => {
  const { calls, fn } = controlled();
  const p = mapLimit([1, 2], 10, fn);
  await tick();
  assert.equal(calls.length, 2);
  calls.forEach((c) => c.resolve(c.item * 2));
  assert.deepEqual(await p, [2, 4]);
});

test('rejection propagates and no more calls launch', async () => {
  const { calls, fn } = controlled();
  const p = mapLimit([0, 1, 2, 3], 2, fn);
  await tick();
