function fakeSleep() {
  const calls = [];
  const sleep = async (ms) => { calls.push(ms); };
  return { sleep, calls };
}

function flaky(failures, value = 'ok') {
  let calls = 0;
  const errors = [];
  const op = async () => {
    calls++;
    if (calls <= failures) {
      const e = new Error('fail ' + calls);
      errors.push(e);
      throw e;
    }
    return value;
  };
  return { op, errors, count: () => calls };
}

