  const { sleep, calls } = fakeSleep();
  const f = flaky(0);
  assert.equal(await retry(f.op, { attempts: 3, delayMs: 10, sleep }), 'ok');
  assert.equal(f.count(), 1);
  assert.deepEqual(calls, []);
});

test('retries failures, sleeping between attempts only', async () => {
  const { sleep, calls } = fakeSleep();
  const f = flaky(2);
  assert.equal(await retry(f.op, { attempts: 5, delayMs: 7, sleep }), 'ok');
  assert.equal(f.count(), 3);
  assert.deepEqual(calls, [7, 7]);
});

