import re

_AGE_RE = re.compile(r"[0-9]+")


def _parse_csv(text):
    """Strict RFC 4180-style parser; raises ValueError on bad quoting."""
    records = []
    fields = []
    field = []
    in_quotes = False   # inside a quoted field
    closed = False      # just closed a quoted field
    started = False     # current field has any content or opening quote
    i, n = 0, len(text)
    while i < n:
        c = text[i]
        if in_quotes:
            if c == '"':
                if text[i + 1:i + 2] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
                    closed = True
            else:
                field.append(c)
        elif c == "," or c in "\r\n":
            fields.append("".join(field))
            field, closed, started = [], False, False
            if c != ",":
                if c == "\r" and text[i + 1:i + 2] == "\n":
                    i += 1
                records.append(fields)
                fields = []
        elif closed:
            raise ValueError("invalid CSV: data after closing quote")
        elif c == '"':
            if started:
                raise ValueError("invalid CSV: quote inside unquoted field")
            in_quotes = started = True
        else:
            field.append(c)
            started = True
        i += 1
    if in_quotes:
        raise ValueError("invalid CSV: unterminated quoted field")
    if fields or started:
        fields.append("".join(field))
        records.append(fields)
    return records


def read_people(text):
    """Parse CSV text with header name,age into a list of {"name", "age"} dicts."""
    records = _parse_csv(text)
    if not records or records[0] != ["name", "age"]:
        raise ValueError("invalid header")
    people = []
    for row in records[1:]:
        if len(row) != 2:
            raise ValueError(f"expected 2 columns, got {len(row)}: {row!r}")
        name, age_text = row
        if not _AGE_RE.fullmatch(age_text):
            raise ValueError(f"invalid age: {age_text!r}")
        age = int(age_text)
        if age > 130:
            raise ValueError(f"age out of range: {age}")
        people.append({"name": name, "age": age})
    return people
