'use strict';

const UNSAFE_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

// Rejects unsafe own keys at any depth, including inside arrays.
function validate(value) {
  if (Array.isArray(value)) {
    for (const item of value) validate(item);
  } else if (isPlainObject(value)) {
    for (const key of Object.getOwnPropertyNames(value)) {
      if (UNSAFE_KEYS.has(key)) {
        throw new TypeError(`Unsafe key rejected: ${key}`);
      }
      validate(value[key]);
    }
  }
}

function clone(value) {
  if (Array.isArray(value)) return value.map(clone);
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) out[key] = clone(value[key]);
    return out;
  }
  return value;
}

function merge(base, override) {
  if (isPlainObject(base) && isPlainObject(override)) {
    const out = {};
    for (const key of Object.keys(base)) {
      out[key] = Object.prototype.hasOwnProperty.call(override, key)
        ? merge(base[key], override[key])
        : clone(base[key]);
    }
    for (const key of Object.keys(override)) {
      if (!Object.prototype.hasOwnProperty.call(base, key)) {
        out[key] = clone(override[key]);
      }
    }
    return out;
  }
  return clone(override);
}

function mergeConfig(base, override) {
  validate(base);
  validate(override);
  if (override === undefined) return clone(base);
  return merge(base, override);
}

module.exports = { mergeConfig };
