'use strict';

function isSafeInt(n) {
  return Number.isSafeInteger(n);
}

function splitCents(total, weights) {
  if (!isSafeInt(total) || total < 0) {
    throw new RangeError('total must be a nonnegative safe integer');
  }
  if (!Array.isArray(weights) || weights.length === 0) {
    throw new RangeError('weights must be a nonempty array');
  }
  let sum = 0;
  for (let i = 0; i < weights.length; i++) {
    const w = weights[i];
    if (!isSafeInt(w) || w <= 0) {
      throw new RangeError('weights must be positive safe integers');
    }
    sum += w;
    if (!isSafeInt(sum) || !isSafeInt(total * w)) {
      throw new RangeError('sum or product exceeds the safe integer range');
    }
  }

  const result = new Array(weights.length);
  const remainders = new Array(weights.length);
  let allocated = 0;
  for (let i = 0; i < weights.length; i++) {
    const product = total * weights[i];
    const base = Math.floor(product / sum);
    // Exact integer remainder; avoids float error in product / sum.
    let rem = product - base * sum;
    let q = base;
    if (rem < 0) { q -= 1; rem += sum; }
    else if (rem >= sum) { q += 1; rem -= sum; }
    result[i] = q;
    remainders[i] = rem;
    allocated += q;
  }

  let left = total - allocated;
  const order = result.map((_, i) => i)
    .sort((a, b) => remainders[b] - remainders[a] || a - b);
  for (let k = 0; k < left; k++) result[order[k]] += 1;
  return result;
}

module.exports = { splitCents };
