const VERSION = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function parse(v) {
  if (typeof v !== 'string') throw new TypeError('version must be a string');
  const m = VERSION.exec(v);
  if (!m) throw new TypeError(`invalid version: ${v}`);
  return m.slice(1);
}

// Components have no leading zeros, so a longer string is a larger number
// and equal-length strings compare lexicographically.
function compareComponent(x, y) {
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

function compareVersion(a, b) {
  const pa = parse(a);
  const pb = parse(b);
  for (let i = 0; i < 3; i++) {
    const c = compareComponent(pa[i], pb[i]);
    if (c !== 0) return c;
  }
  return 0;
}

module.exports = { compareVersion };

const test = require('node:test');
const assert = require('node:assert');
const { compareVersion } = require('./solution.cjs');

test('numeric, not lexicographic, ordering', () => {
  assert.strictEqual(compareVersion('1.10.0', '1.2.9'), 1);
  assert.strictEqual(compareVersion('1.2.9', '1.10.0'), -1);
});

test('huge components', () => {
  const big = '9007199254740993'; // MAX_SAFE_INTEGER + 2
  const bigger = '9007199254740992';
  assert.strictEqual(compareVersion(`${big}.0.0`, `${bigger}.0.0`), 1);
  assert.strictEqual(compareVersion(`0.${bigger}.0`, `0.${big}.0`), -1);
  assert.strictEqual(compareVersion(`0.0.${'9'.repeat(40)}`, `0.0.1${'0'.repeat(40)}`), -1);
  assert.strictEqual(compareVersion(`${big}.${big}.${big}`, `${big}.${big}.${big}`), 0);
});

test('equality and earlier component dominates', () => {
  assert.strictEqual(compareVersion('0.0.0', '0.0.0'), 0);
  assert.strictEqual(compareVersion('1.2.3', '1.2.3'), 0);
  assert.strictEqual(compareVersion('2.0.0', '1.99.99'), 1);
});

