class Emitter {
  #events = new Map(); // event -> Map(fn -> registration)

  on(event, fn) {
    let regs = this.#events.get(event);
    if (!regs) this.#events.set(event, (regs = new Map()));
    let reg = regs.get(fn);
    if (!reg) regs.set(fn, (reg = { fn }));
    return () => {
      // Only remove our own registration, not a later re-registration.
      const current = this.#events.get(event);
      if (current && current.get(fn) === reg) this.off(event, fn);
    };
  }

  off(event, fn) {
    const regs = this.#events.get(event);
    if (!regs) return;
    regs.delete(fn);
    if (regs.size === 0) this.#events.delete(event);
  }

  emit(event, value) {
    const regs = this.#events.get(event);
    if (!regs) return;
    for (const fn of [...regs.keys()]) fn(value);
  }
}

module.exports = { Emitter };
